insert into public.faq_items (key, category, q_ar, q_en, a_ar, a_en, sort) values
  ($faq$confirmation$faq$, $faq$booking$faq$, $faq$كيف أعرف أن حجزي مؤكد؟$faq$, $faq$How do I know my booking is confirmed?$faq$, $faq$إذا ظهرت علامة «تأكيد فوري» بعد اختيار التواريخ، يتأكد حجزك مباشرة عند الإرسال، ويصلك التأكيد عبر الواتساب والبريد الإلكتروني إن أدخلته. وإذا لم تظهر، فما ترسله طلب حجز يراجعه الاستقبال ويؤكد لك التوافر والسعر.$faq$, $faq$If you see “Instant confirmation” after choosing your dates, your booking is confirmed as soon as you submit it, and the confirmation reaches you on WhatsApp, and by email if you gave one. Otherwise, what you send is a booking request: reception reviews it and confirms availability and the price with you.$faq$, 0),
  ($faq$cancellation$faq$, $faq$booking$faq$, $faq$ما سياسة الإلغاء؟$faq$, $faq$What is the cancellation policy?$faq$, $faq$الإلغاء مجاني حتى 24 ساعة قبل موعد الوصول. بعد ذلك، أو في حال عدم الحضور، تُحسب قيمة الليلة الأولى. تنطبق هذه السياسة على الحجز المباشر عبر الموقع والواتساب والاستقبال؛ أما الحجوزات عبر منصات الحجز الأخرى فتخضع لسياسة المنصة.$faq$, $faq$Cancellation is free until 24 hours before arrival. After that, or if you don't arrive, the first night is charged. This applies to direct bookings through the website, WhatsApp and reception; bookings made on other booking platforms follow that platform's policy.$faq$, 1),
  ($faq$payment$faq$, $faq$booking$faq$, $faq$متى وكيف أدفع؟$faq$, $faq$When and how do I pay?$faq$, $faq$يُسدَّد المبلغ عند الوصول في الاستقبال، ولا نطلب أي دفعة مسبقة. نقبل مدى وفيزا والدفع النقدي.$faq$, $faq$You pay at reception when you arrive; no prepayment is required. We accept mada, Visa and cash.$faq$, 2),
  ($faq$guests-extra-bed$faq$, $faq$booking$faq$, $faq$كم شخصًا يشمل السعر؟ وهل يمكن إضافة سرير؟$faq$, $faq$How many guests does the price cover? Can I add a bed?$faq$, $faq$يشمل سعر الغرفة والاستديو وجناح الغرفة والصالة شخصين بالغين، ويشمل سعر الأجنحة بغرفتي نوم أربعة أشخاص، والأطفال لا يُحسبون ضمن العدد المشمول. ويمكن إضافة سرير إضافي في بعض أنواع الغرف برسوم {extra_bed} لليلة، تختاره عند الحجز.$faq$, $faq$Rooms, studios and one-bedroom suites are priced for two adults, and two-bedroom suites for four; children aren't counted. An extra bed can be added in selected room types for {extra_bed} per night, chosen when you book.$faq$, 3),
  ($faq$check-in-out$faq$, $faq$stay$faq$, $faq$ما مواعيد الوصول والمغادرة؟$faq$, $faq$What are the check-in and check-out times?$faq$, $faq$الوصول من الساعة 4:00 عصرًا، والمغادرة حتى الساعة 12:00 ظهرًا، في الفرعين. ويمكنكم الوصول في أي وقت بعد الرابعة، فالاستقبال متاح على مدار الساعة.$faq$, $faq$Check-in is from 4:00 pm and check-out is by 12:00 noon at both properties. You can arrive at any time after 4:00 pm, as reception is open around the clock.$faq$, 4),
  ($faq$early-late$faq$, $faq$stay$faq$, $faq$هل يمكن الوصول مبكرًا أو المغادرة متأخرًا؟$faq$, $faq$Can I check in early or check out late?$faq$, $faq$حسب التوافر، ويُطلب ذلك من الاستقبال مسبقًا. المغادرة المتأخرة برسوم: 100 ريال حتى 2:00 ظهرًا، و200 ريال حتى 4:00 عصرًا.$faq$, $faq$Subject to availability; please ask reception in advance. Late check-out is SAR 100 until 2:00 pm and SAR 200 until 4:00 pm.$faq$, 5),
  ($faq$breakfast$faq$, $faq$stay$faq$, $faq$هل الإفطار مشمول؟$faq$, $faq$Is breakfast included?$faq$, $faq$الإفطار اختياري تختاره عند الحجز، ورسومه {breakfast} للشخص في الليلة، والأطفال حتى 5 سنوات مجانًا ومن 6 إلى 12 سنة بنصف الرسوم. يُقدَّم بوفيه الإفطار يوميًا في مطعم كل فرع من 7:00 إلى 10:30 صباحًا.$faq$, $faq$Breakfast is optional and chosen when you book, at {breakfast} per person per night; children up to 5 eat free and ages 6 to 12 pay half. The breakfast buffet is served daily in each property's restaurant from 7:00 to 10:30 am.$faq$, 6),
  ($faq$id$faq$, $faq$stay$faq$, $faq$ما المستندات المطلوبة عند الوصول؟$faq$, $faq$What do I need to show at check-in?$faq$, $faq$يُطلب إثبات هوية سارٍ لصاحب الحجز: هوية وطنية أو إقامة أو جواز سفر.$faq$, $faq$The guest who made the booking needs a valid ID: a national ID, an iqama or a passport.$faq$, 7),
  ($faq$wifi$faq$, $faq$stay$faq$, $faq$هل يوجد واي فاي؟$faq$, $faq$Is there Wi-Fi?$faq$, $faq$نعم، الواي فاي مجاني في جميع الغرف.$faq$, $faq$Yes, Wi-Fi is free in every room.$faq$, 8),
  ($faq$dining-housekeeping$faq$, $faq$stay$faq$, $faq$هل يوجد توصيل طعام إلى الغرف؟ ومتى تُنظَّف الغرف؟$faq$, $faq$Is there in-room dining? When are rooms cleaned?$faq$, $faq$نعم، توصيل الطعام إلى الغرف متاح على مدار الساعة في الفرعين، وتُنظَّف الغرف يوميًا من 10:00 صباحًا حتى 5:00 مساءً.$faq$, $faq$Yes, in-room dining is available around the clock at both properties, and rooms are cleaned daily between 10:00 am and 5:00 pm.$faq$, 9),
  ($faq$smoking$faq$, $faq$stay$faq$, $faq$هل التدخين مسموح في الغرف؟$faq$, $faq$Is smoking allowed in the rooms?$faq$, $faq$جميع الغرف لغير المدخنين.$faq$, $faq$All rooms are non-smoking.$faq$, 10),
  ($faq$pets$faq$, $faq$stay$faq$, $faq$هل يُسمح باصطحاب الحيوانات الأليفة؟$faq$, $faq$Are pets allowed?$faq$, $faq$لا، الحيوانات الأليفة غير مسموح بها.$faq$, $faq$No, pets aren't allowed.$faq$, 11),
  ($faq$accessible$faq$, $faq$stay$faq$, $faq$هل توجد غرف مهيأة لذوي الاحتياجات الخاصة؟$faq$, $faq$Do you have accessible rooms?$faq$, $faq$نعم، يتوفر في كل فرع غرفة مهيأة لذوي الاحتياجات الخاصة. لمعرفة تفاصيل تجهيزاتها قبل الحجز، تواصلوا مع الاستقبال.$faq$, $faq$Yes, each property has an accessible room. For details of its facilities before booking, please contact reception.$faq$, 12),
  ($faq$parking$faq$, $faq$branches$faq$, $faq$هل يوجد موقف سيارات؟$faq$, $faq$Is there parking?$faq$, $faq$نعم، المواقف مجانية في الفرعين.$faq$, $faq$Yes, parking is free at both properties.$faq$, 13),
  ($faq$branches$faq$, $faq$branches$faq$, $faq$ما الفرق بين الفرعين؟$faq$, $faq$What's the difference between the two properties?$faq$, $faq$فرع طريق المطار شقق فندقية تضم غرفًا وأجنحة بعضها بمطبخ، مع مطعم ومقهى على مدار الساعة وقاعة للاجتماعات. وفندق طريق الشفا يضم غرفًا وأجنحة، منها وحدات بجاكوزي خاص وغرفة ببلكونة، ويقع على الطريق إلى مرتفعات الشفا.$faq$, $faq$Airport Road offers hotel apartments: rooms and suites, some with a kitchen, plus a 24-hour restaurant and café and a meeting hall. The Shafa Road hotel offers rooms and suites, including units with a private jacuzzi and a balcony room, on the road to the Al-Shafa highlands.$faq$, 14),
  ($faq$contact$faq$, $faq$branches$faq$, $faq$كيف أتواصل مع الاستقبال؟$faq$, $faq$How do I contact reception?$faq$, $faq$تواصلوا مع استقبال الفرع مباشرة عبر زر الواتساب في صفحة كل فرع، والاستقبال متاح على مدار الساعة.$faq$, $faq$Message the property's reception directly with the WhatsApp button on its page; reception is available around the clock.$faq$, 15),
  ($faq$airport$faq$, $faq$branches$faq$, $faq$كم يبعد فرع طريق المطار عن مطار الطائف؟$faq$, $faq$How far is Airport Road from Taif airport?$faq$, $faq$يبعد فرع طريق المطار عن مطار الطائف الدولي نحو 22 كيلومترًا، أي قرابة 18 دقيقة بالسيارة.$faq$, $faq$Airport Road is about 22 km from Taif International Airport, around 18 minutes by car.$faq$, 16),
  ($faq$hall$faq$, $faq$business$faq$, $faq$هل لديكم قاعة للاجتماعات والمناسبات؟$faq$, $faq$Do you have a meeting and events hall?$faq$, $faq$نعم، في فرع طريق المطار قاعة تتسع حتى 50 شخصًا، مجهزة ببروجكتر ونظام صوتي وخمسة أنماط للجلوس. للأسعار والحجز، اطلبوا عرض سعر من صفحة القاعة وسيتواصل معكم فريق المبيعات.$faq$, $faq$Yes, Airport Road has a hall for up to 50 guests, with a projector, a sound system and five seating layouts. For prices and bookings, request a quote from the hall page and our sales team will contact you.$faq$, 17),
  ($faq$groups$faq$, $faq$business$faq$, $faq$هل لديكم أسعار للشركات والمجموعات؟$faq$, $faq$Do you have rates for companies and groups?$faq$, $faq$نعم، للشركات والمجموعات وشركات السياحة صفحة «للشركاء والوكالات»، يمكنكم منها إرسال طلب عرض سعر، ويتواصل معكم فريق المبيعات.$faq$, $faq$Yes. Companies, groups and travel agencies can send a quote request from our “Partners and agencies” page, and our sales team will contact you.$faq$, 18)
